import { expect, it } from "vitest";
import { compile } from "../src/index.js";

const cases = [
  {
    name: "computed Symbol method keeps key evaluation, name, captures, receiver and lazy resumptions",
    source: `export function test() {
      let keys = 0;
      let steps = 0;
      let offset = 3;
      const key = Symbol("floor");
      function getKey() { keys++; return key; }
      const object = {
        value: 7,
        get size() { return steps; },
        *[getKey()]() { steps++; yield this.value + offset; steps++; yield this.value + offset; }
      };
      if (keys !== 1 || steps !== 0) return -1;
      const descriptor = Object.getOwnPropertyDescriptor(object[key], "name");
      if (descriptor.value !== "[floor]" || descriptor.writable !== false ||
          descriptor.enumerable !== false || descriptor.configurable !== true) return -2;
      const iterator = object[key]();
      if (steps !== 0) return -3;
      const other = { value: 99, read() { return this.value; } };
      other.read();
      const first = iterator.next();
      if (first.done || first.value !== 10 || steps !== 1) return -4;
      object.value = 9;
      offset = 4;
      other.read();
      const second = iterator.next();
      if (second.done || second.value !== 13 || steps !== 2) return -5;
      const end = iterator.next();
      if (!end.done || end.value !== undefined || !iterator.next().done) return -6;
      return keys === 1 && steps === 2 ? 1 : -7;
    }`,
  },
  {
    name: "different runtime Symbol keys with the same description retain distinct factories",
    source: `export function test() {
      const a = Symbol("same");
      const b = Symbol("same");
      let steps = 0;
      const object = {
        *[a]() { steps++; yield 11; },
        *[b]() { steps++; yield 22; }
      };
      const left = object[a]();
      const right = object[b]();
      if (steps !== 0) return -1;
      if (left.next().value !== 11 || right.next().value !== 22 || steps !== 2) return -2;
      if (!left.next().done || !right.next().done) return -3;
      return object[a] !== object[b] ? 1 : -4;
    }`,
  },
  {
    name: "abrupt computed-key evaluation runs once and prevents later properties and generator execution",
    source: `export function test() {
      let keys = 0;
      let steps = 0;
      let later = 0;
      const marker = {};
      function fail() { keys++; throw marker; }
      function after() { later++; return 1; }
      try {
        const object = { *[fail()]() { steps++; yield 1; }, later: after() };
        return -1;
      } catch (error) {
        return error === marker && keys === 1 && steps === 0 && later === 0 ? 1 : -2;
      }
    }`,
  },
];

// Keep the original three sources above unchanged. A partially constructed
// object literal is not observable in JS: capture the previously published
// method during replacement-key evaluation, not an inaccessible literal slot.
const duplicateCases = [
  {
    name: "duplicate synchronous names preserve a saved factory across replacement key evaluation",
    source: `export function test() {
      let steps = 0;
      let keys = 0;
      let saved;
      let object = { get marker() { return 0; }, *same() { steps++; yield 11; } };
      function replacementKey() { keys++; saved = object.same; return "same"; }
      object = {
        get marker() { return 0; },
        *same() { steps += 100; yield 99; },
        *[replacementKey()]() { steps++; yield 22; }
      };
      if (keys !== 1 || steps !== 0 || saved === object.same) return -1;
      const first = saved();
      const last = object.same();
      if (steps !== 0) return -2;
      if (first.next().value !== 11 || last.next().value !== 22 || steps !== 2) return -3;
      if (!first.next().done || !last.next().done || keys !== 1) return -4;
      return saved.name === "same" && object.same.name === "same" ? 1 : -5;
    }`,
  },
  {
    name: "literal duplicate synchronous names select the last independent lazy factory",
    source: `export function test() {
      let steps = 0;
      const object = {
        get marker() { return 0; },
        *same() { steps += 100; yield 99; },
        *same() { steps++; yield 22; }
      };
      const first = object.same();
      const second = object.same();
      if (steps !== 0) return -1;
      if (first === second) return -2;
      if (first.next().value !== 22 || second.next().value !== 22 || steps !== 2) return -3;
      return first.next().done && second.next().done ? 1 : -4;
    }`,
  },
  {
    name: "an async spelling collision does not reject the later synchronous lazy method",
    source: `export function test() {
      let steps = 0;
      const object = {
        get marker() { return 0; },
        async *same() {},
        *same() { steps++; yield 33; }
      };
      const iterator = object.same();
      if (steps !== 0) return -1;
      const first = iterator.next();
      if (first.done || first.value !== 33 || steps !== 1) return -2;
      return iterator.next().done && object.same.name === "same" ? 1 : -3;
    }`,
  },
];

for (const optimize of [0, 2] as const) {
  for (const fixture of [...cases, ...duplicateCases]) {
    it(`${fixture.name} O${optimize}`, async () => {
      // Native JS is an independent oracle, not a compiler-derived expectation.
      const reference = new Function(fixture.source.replace("export function test", "function test") + "; return test();");
      expect(reference()).toBe(1);
      const result = await compile(fixture.source, {
        fileName: "5753-computed-generator-floor.js",
        allowJs: true,
        skipSemanticDiagnostics: true,
        target: "standalone",
        optimize,
      });
      expect(result.success, JSON.stringify(result.errors)).toBe(true);
      const module = new WebAssembly.Module(result.binary);
      expect(WebAssembly.Module.imports(module)).toEqual([]);
      const instance = new WebAssembly.Instance(module, {});
      expect((instance.exports.test as () => number)()).toBe(1);
    });
  }
}

