import { expect, it } from "vitest";
import { compile } from "../src/index.js";

// Unrun source witnesses for the lifted-object-method admission review.
// Pair these exact sources before/after the generator patch. The old unresolved
// method-key refusal selected a host-backed fallback, not proven correct native
// execution. Do not treat that baseline limitation as an expected JS result.
const cases = [
  {
    name: "computed class field key preserves the generator's call-time receiver",
    source: `export function test() {
      const key = Symbol("receiver");
      let observed = 0;
      let evaluations = 0;
      function record(value) { evaluations++; observed = value; return "field"; }
      const object = {
        key: 17,
        get marker() { return 0; },
        *[key]() {
          class C { [record(this.key)] = 1; }
          yield observed;
        }
      };
      const iterator = object[key]();
      if (evaluations !== 0) return -1;
      const other = { key: 99, read() { return this.key; } };
      if (other.read() !== 99) return -2;
      const first = iterator.next();
      if (first.done || first.value !== 17 || evaluations !== 1) return -3;
      return iterator.next().done && evaluations === 1 ? 1 : -4;
    }`,
  },
  {
    name: "class heritage preserves the generator's call-time receiver",
    source: `export function test() {
      const key = Symbol("receiver");
      class Base {}
      let observed;
      let evaluations = 0;
      function record(value) { evaluations++; observed = value; return value; }
      const object = {
        Base,
        get marker() { return 0; },
        *[key]() {
          class C extends record(this.Base) {}
          yield observed === Base ? 1 : -10;
        }
      };
      const iterator = object[key]();
      if (evaluations !== 0) return -1;
      const other = { value: 99, read() { return this.value; } };
      if (other.read() !== 99) return -2;
      const first = iterator.next();
      if (first.done || first.value !== 1 || evaluations !== 1) return -3;
      return iterator.next().done && evaluations === 1 ? 1 : -4;
    }`,
  },
] as const;

for (const optimize of [0, 2] as const) {
  for (const fixture of cases) {
    it(`${fixture.name} O${optimize}`, async () => {
      const reference = new Function(
        '"use strict";\n' + fixture.source.replace("export function test", "function test") + "\nreturn test();",
      );
      expect(reference()).toBe(1);
      const result = await compile(fixture.source, {
        fileName: "5753-generator-class-receiver-scan.js",
        allowJs: true,
        skipSemanticDiagnostics: true,
        target: "standalone",
        optimize,
      });
      expect(result.success, JSON.stringify(result.errors)).toBe(true);
      const module = new WebAssembly.Module(result.binary);
      expect(WebAssembly.Module.imports(module)).toEqual([]);
      const instance = new WebAssembly.Instance(module, {});
      expect((instance.exports.test as () => number)()).toBe(1);
    });
  }
}

