import { expect, it } from "vitest";
import { compile } from "../src/index.js";

// Additive diagnostic, not an edit to the original Test262 fixture.
const prefix = `var nativeErrors = [Error, EvalError, RangeError, ReferenceError, SyntaxError, TypeError, URIError];`;
const cases = [
  {
    name: "dynamic Error constructor produces real named message-bearing objects",
    source: `${prefix}
      export function test() {
        for (var i = 0; i < nativeErrors.length; ++i) {
          var Ctor = nativeErrors[i];
          var err = new Ctor('msg');
          if (err === undefined) return 100 + i;
          if (err === null) return 200 + i;
          if (typeof err !== 'object') return 300 + i;
          if (err.message !== 'msg') return 400 + i;
          if (err.name !== Ctor.name) return 500 + i;
          var another = new Ctor('other');
          if (err === another || another.message !== 'other') return 600 + i;
        }
        return 1;
      }`,
  },
  {
    name: "borrowed own-property method receives the actual constructed Error",
    source: `${prefix}
      export function test() {
        for (var i = 0; i < nativeErrors.length; ++i) {
          var Ctor = nativeErrors[i];
          var err = new Ctor('msg');
          if (err === null || err === undefined) return 100 + i;
          if (!Object.prototype.hasOwnProperty.call(err, 'message')) return 200 + i;
          if (Object.prototype.hasOwnProperty.call(err, 'missing')) return 300 + i;
        }
        return 1;
      }`,
  },
] as const;

for (const fixture of cases) {
  it(fixture.name, async () => {
    const reference = new Function(
      '"use strict";\n' + fixture.source.replace("export function test", "function test") + "\nreturn test();",
    );
    expect(reference()).toBe(1);
    const result = await compile(fixture.source, {
      fileName: "5753-error-constructor-diagnostic.js",
      allowJs: true,
      skipSemanticDiagnostics: true,
      target: "standalone",
      optimize: 0,
    });
    expect(result.success, JSON.stringify(result.errors)).toBe(true);
    const module = new WebAssembly.Module(result.binary);
    expect(WebAssembly.Module.imports(module)).toEqual([]);
    const instance = new WebAssembly.Instance(module, {});
    const actual = (instance.exports.test as () => number)();
    console.log(JSON.stringify({ name: fixture.name, source: fixture.source, expected: 1, actual }));
    expect(actual).toBe(1);
  });
}

