import { expect, it } from "vitest";
import { compile } from "../src/index.js";

// Diagnostic acceptance tests, not preservation of the compiler's wrong answers.
// Each source has an independent native-JavaScript expectation of 1. Keep the
// identity, value, descriptor and reentrant cases separate so an early identity
// failure cannot conceal all of the storage obligations. Not run when added.
const cases = [
  {
    name: "one class-expression site creates distinct constructors and prototypes",
    source: `
      function make() { return class {}; }
      export function test() {
        const first = make();
        const second = make();
        if (first === second) return -1;
        if (first.prototype === second.prototype) return -2;
        if (first.prototype.constructor !== first) return -3;
        if (second.prototype.constructor !== second) return -4;
        return 1;
      }`,
  },
  {
    name: "earlier static values survive later evaluations and independent writes",
    source: `
      let sequence = 0;
      function make() { return class { static value = ++sequence; }; }
      export function test() {
        const first = make();
        const second = make();
        if (sequence !== 2) return -1;
        if (first.value !== 1 || second.value !== 2) return -2;
        first.value = 17;
        if (first.value !== 17 || second.value !== 2) return -3;
        second.value = 29;
        return first.value === 17 && second.value === 29 ? 1 : -4;
      }`,
  },
  {
    name: "nonconfigurable earlier statics do not poison later definition delete or re-add",
    source: `
      function make() { return class { static value = 7; }; }
      export function test() {
        const first = make();
        Object.defineProperty(first, "value", {
          value: 41, writable: false, enumerable: true, configurable: false
        });
        const second = make();
        const before = Object.getOwnPropertyDescriptor(second, "value");
        if (!before || before.value !== 7 || before.writable !== true ||
            before.enumerable !== true || before.configurable !== true) return -1;
        if (!delete second.value) return -2;
        if (Object.prototype.hasOwnProperty.call(second, "value")) return -3;
        if (!Object.prototype.hasOwnProperty.call(first, "value")) return -4;
        Object.defineProperty(second, "value", {
          value: 73, writable: true, enumerable: true, configurable: true
        });
        const earlier = Object.getOwnPropertyDescriptor(first, "value");
        if (!earlier || earlier.value !== 41 || earlier.writable !== false ||
            earlier.configurable !== false) return -5;
        return first.value === 41 && second.value === 73 ? 1 : -6;
      }`,
  },
  {
    name: "reentrant evaluation keeps the suspended outer constructor and static store",
    source: `
      let depth = 0;
      let inner;
      function initialValue() {
        if (depth++ === 0) {
          inner = make();
          return 11;
        }
        return 22;
      }
      function make() { return class { static value = initialValue(); }; }
      export function test() {
        const outer = make();
        if (depth !== 2) return -1;
        if (outer.value !== 11 || inner.value !== 22) return -2;
        if (outer === inner || outer.prototype === inner.prototype) return -3;
        inner.value = 31;
        return outer.value === 11 && inner.value === 31 ? 1 : -4;
      }`,
  },
] as const;

for (const optimize of [0, 2] as const) {
  for (const fixture of cases) {
    it(`${fixture.name} O${optimize}`, async () => {
      // Both sources have module/strict semantics. This native oracle neither
      // consults compiler output nor substitutes an observed baseline value.
      const reference = new Function(
        '"use strict";\n' + fixture.source.replace("export function test", "function test") + "\nreturn test();",
      );
      expect(reference()).toBe(1);
      const result = await compile(fixture.source, {
        fileName: "5753-class-evaluation-ownership.js",
        allowJs: true,
        skipSemanticDiagnostics: true,
        target: "standalone",
        optimize,
      });
      expect(result.success, JSON.stringify(result.errors)).toBe(true);
      const module = new WebAssembly.Module(result.binary);
      expect(WebAssembly.Module.imports(module)).toEqual([]);
      const instance = new WebAssembly.Instance(module, {});
      expect((instance.exports.test as () => number)()).toBe(1);
    });
  }
}

